      "resumo": "É o contrário: **Windows + seta para a esquerda** encaixa a janela na **metade esquerda**; **Windows + seta para cima** **maximiza**; Windows + seta para baixo minimiza/restaura. Fonte: Suporte Microsoft, \"Atalhos de teclado no Windows\" (consultado em 08/11/2026).",
