      "aprofundamento": "A seleção no Explorador segue duas lógicas diferentes. O **Shift** pensa em intervalo: marca tudo do primeiro item clicado até o último, sem buracos. O **Ctrl** pensa em itens avulsos: cada clique acrescenta ou retira um item da seleção, sem afetar os outros.\n\nAs duas podem ser combinadas: um intervalo com Shift e, depois, itens soltos com Ctrl. O mesmo raciocínio vale para o Excel, ao selecionar células.\n\nNa assertiva, clicar em 2 e, com Shift, em 8, selecionaria do 2 ao 8 inteiro. A palavra \"apenas\" com itens salteados exige o Ctrl.",
