      "aprofundamento": "As teclas de função têm papéis estáveis em quase todo o Windows. **F2** é a de renomear no Explorador (e de editar a célula no Excel); **F5** é a de atualizar o conteúdo da janela, como no navegador.\n\nAo renomear, o Windows seleciona só o nome, deixando a extensão de fora, justamente para evitar que o usuário a apague sem querer. Se a extensão for alterada, o sistema avisa que o arquivo pode ficar inutilizável, porque é ela que indica qual programa o abre.\n\nA banca troca uma tecla de função pela outra. Associar F5 a \"recarregar\" ajuda a não cair.",
