      "aprofundamento": "As Configurações do Windows 11 são divididas por assunto. **Sistema** trata do funcionamento do computador: tela, som, notificações, energia, armazenamento; dentro dele, **Sobre** é uma página informativa, que mostra processador, memória, nome do dispositivo e versão do Windows.\n\nTudo o que diz respeito à aparência fica em **Personalização**: plano de fundo, cores, modo claro ou escuro, cor de destaque, temas, tela de bloqueio, Iniciar e barra de tarefas.\n\nA banca troca a seção. Pergunta útil para resolver: \"isso muda o visual ou o funcionamento?\". Visual é Personalização.",
