      "aprofundamento": "A **proteção de tela** nasceu para evitar que monitores antigos ficassem com a imagem gravada quando exibiam a mesma tela por muito tempo. Nos monitores atuais esse risco é menor, e a função perdeu destaque, mas não foi retirada.\n\nNo Windows 11 ela fica escondida: dentro de Personalização, na página da tela de bloqueio, há o link que abre a janela clássica, onde se escolhe a proteção, o tempo de espera e a opção de exigir login ao retomar. Esta última é o uso de segurança que ainda faz sentido.\n\nA banca aposta que o candidato não encontrou o recurso e o dá por extinto. Mudança de lugar não é eliminação.",
