      "aprofundamento": "A **impressora padrão** é a que o Windows usa quando o usuário manda imprimir sem escolher destino. Por definição só pode haver uma: se houvesse várias padrão, o sistema não saberia para qual enviar.\n\nCom a opção de deixar o Windows gerenciar a padrão ligada, ela muda sozinha para a última impressora usada naquele local. Desligando a opção, o usuário escolhe uma e a define como padrão manualmente.\n\nA assertiva é um exemplo da técnica de começar certo e terminar errado: o caminho de Bluetooth e dispositivos está correto; o erro está na segunda parte. Leia a frase até o fim.",
