      "aprofundamento": "No Explorador, a navegação tem três movimentos com Alt e setas: seta para a esquerda volta à pasta anterior (como o botão Voltar), seta para a direita avança, e **seta para cima** sobe para a pasta que contém a atual, a pasta \"mãe\".\n\nVoltar e subir não são a mesma coisa: voltar refaz o histórico; subir segue a hierarquia de pastas. Se o usuário chegou a uma pasta por um atalho, voltar e subir levam a lugares diferentes.\n\nO **painel de visualização** mostra o conteúdo do arquivo sem abri-lo e é ligado ou desligado com Alt + P. A banca troca os efeitos dos dois atalhos.",
