      "aprofundamento": "A escolha de ocultar as **extensões** dos tipos conhecidos foi feita para deixar a lista de arquivos mais limpa para o usuário comum. O custo é de segurança: sem ver a extensão real, a pessoa não percebe que \"foto.jpg\" é, na verdade, \"foto.jpg.exe\", um programa executável disfarçado.\n\nPor isso a recomendação de segurança é exibir as extensões, pela guia Exibir. Tipos que o Windows não reconhece já aparecem com a extensão.\n\nA banca inverte o padrão. A palavra \"inclusive dos tipos conhecidos\" é exatamente o ponto em que a frase erra.",
      "exemplo": "Um anexo aparece como 'boleto.pdf' com ícone de documento; com as extensões visíveis, o usuário vê 'boleto.pdf.exe' e percebe o golpe.",
