      "resumo": "É o contrário: a **coautoria** exige o arquivo na **nuvem** (OneDrive/SharePoint), compartilhado por link; ali a edição é **simultânea**, com o **Salvamento Automático** gravando as alterações. Cópias por e-mail viram versões separadas.",
      "pegadinha": "Ligar a coautoria a cópias locais.",
