      "correcao": {
       "erro": "Condiciona a coautoria ao arquivo salvo no disco local de cada coautor e enviado por e-mail.",
       "certo": "A coautoria exige o arquivo na nuvem (OneDrive ou SharePoint), compartilhado por link; ali várias pessoas editam ao mesmo tempo, e o Salvamento Automático grava as alterações."
      },
      "aprofundamento": "**Coautoria** depende de haver um único arquivo que todos acessam ao mesmo tempo. Isso só existe quando o documento está na nuvem, no OneDrive ou no SharePoint: cada pessoa abre o mesmo arquivo, vê a presença dos demais e as alterações chegam quase em tempo real.\n\nMandar o arquivo por e-mail faz o oposto: cada destinatário passa a ter sua cópia, e as alterações se tornam versões separadas que alguém precisará juntar depois.\n\nA banca inverte o requisito. A palavra \"disco local\" é o sinal de erro em qualquer frase sobre edição simultânea.",
