      "aprofundamento": "O **Painel de Navegação** depende dos estilos de título para funcionar como índice interativo. O Word identifica cada parágrafo com estilo Título 1, Título 2 e assim por diante e os lista em árvore. Clicando num título, salta-se até ele; arrastando, move-se a seção inteira com seu conteúdo.\n\nO painel tem outras abas: páginas em miniatura e resultados de pesquisa, já que ele também é aberto pelo atalho de busca.\n\nA banca separa as duas coisas e diz que o painel mostra só páginas. É a mesma lógica do sumário: sem estilo de título, nada aparece na lista de títulos.",
