      "resumo": "No **Writer**, **F11** abre o **Estilos** na barra lateral; o Writer separa estilos de **parágrafo, caractere, quadro, página, lista** e tabela — o estilo de **página** é marca do LibreOffice. Atalho do LibreOffice 7.x/24.x em configuração padrão.",
