      "aprofundamento": "Cabeçalho e rodapé são áreas reservadas nas margens superior e inferior da página. Como se trata de inserir um elemento no documento, os comandos ficam na guia **Inserir**, no grupo próprio, ao lado do Número de Página.\n\nAo entrar no cabeçalho, surge uma guia contextual com opções como Primeira Página Diferente, Páginas Pares e Ímpares Diferentes e o fechamento da área. O duplo clique na parte de cima ou de baixo da página é o atalho de mouse para editar.\n\nA banca pode situar esses comandos em Layout ou Referências. A assertiva aponta o lugar correto.",
