      "aprofundamento": "A capa normalmente não leva número de página nem cabeçalho, mas continua sendo contada como página. **Primeira Página Diferente** resolve isso: a primeira página da seção ganha cabeçalho e rodapé próprios, que podem ficar vazios, enquanto as seguintes mantêm o padrão.\n\nA opção aparece na guia contextual que surge ao editar o cabeçalho. Ela vale por seção: se o documento tiver várias seções, cada uma pode ter sua primeira página diferente.\n\nA banca pode dizer que a opção apaga a numeração do documento inteiro ou que exige criar outro arquivo.",
