      "aprofundamento": "Em livros impressos frente e verso, as páginas ímpares ficam à direita e as pares à esquerda. Por isso costuma-se pôr o número sempre no lado externo, e o nome do capítulo de um lado e o do livro do outro.\n\nA opção **Páginas Pares e Ímpares Diferentes** cria dois cabeçalhos e dois rodapés para cada seção, um para as pares e outro para as ímpares. Ela fica na guia contextual de cabeçalho e rodapé e pode ser combinada com a primeira página diferente.\n\nA banca nega o recurso. Negativas absolutas sobre o Word quase sempre estão erradas.",
