      "aprofundamento": "O grupo **Configurar Página** reúne o que define a folha: margens, orientação, tamanho do papel, colunas e quebras. **Retrato** é a página em pé, mais alta que larga, padrão dos documentos de texto; **paisagem** é a página deitada, útil para tabelas largas e gráficos.\n\nA orientação vale para a seção. Se houver uma só seção, muda o documento inteiro; com quebras de seção, pode ser escolhida página a página.\n\nA banca costuma situar a orientação na guia Exibir ou Design. Quem define a folha é Layout.",
