      "resumo": "O arquivo (.xlsx) é a **pasta de trabalho**; cada **planilha** é uma guia (Planilha1, Planilha2...). **Shift + F11** insere nova planilha. Fonte: Suporte Microsoft, \"Atalhos de teclado no Excel\" (consultado em 08/11/2026).",
