      "aprofundamento": "A terminologia do Excel imita uma pasta de escritório. A **pasta de trabalho** é o arquivo inteiro; dentro dela ficam as **planilhas**, como folhas, cada uma com sua guia na parte inferior. As fórmulas podem buscar dados de outras planilhas da mesma pasta.\n\nAs planilhas podem ser renomeadas, coloridas, reordenadas e ocultadas pelo menu do botão direito na guia. O Shift + F11 insere nova planilha antes da atual.\n\nA banca troca os termos, chamando o arquivo de planilha e a guia de pasta. A pasta contém; a planilha é contida.",
