     "gabarito": "C",
     "comentario": {
      "resumo": "Nas versões desde 2007: **1.048.576 linhas** × **16.384 colunas** (de A até **XFD**). O formato .xls antigo tinha 65.536 linhas e 256 colunas.",
      "palavras_chave": [
       "1.048.576 linhas",
       "XFD"
      ],
      "aprofundamento": "Os limites da planilha mudaram com o formato .xlsx. A grade passou a ter 1.048.576 linhas e 16.384 colunas, contra os limites bem menores do antigo .xls. As colunas, depois do Z, seguem com duas letras (AA, AB...) e depois três, até a última, XFD.\n\nPor isso, ao abrir um arquivo grande no formato antigo, ou salvar uma planilha extensa em .xls, o Excel avisa que dados além do limite seriam perdidos.\n\nA banca troca os números de linhas e colunas entre si ou usa os limites do formato antigo. Lembre: linhas são muito mais numerosas que colunas.",
      "memorize": "Excel atual: 1.048.576 linhas × 16.384 colunas (última: XFD)."
     }
