      "resumo": "**PROCV** procura na **primeira coluna** da matriz e devolve o valor da coluna indicada **à direita** (núm_índice_coluna); o último argumento **FALSO** pede correspondência **exata**. Para buscar \"à esquerda\", usa-se **PROCX** (Microsoft 365/2021) ou ÍNDICE com CORRESP. Fonte: Suporte Microsoft, \"Funções do Excel (por categoria)\" (consultado em 08/11/2026).",
