      "aprofundamento": "Sem quebra, um texto longo invade visualmente as células vizinhas vazias ou fica cortado se elas tiverem conteúdo. **Quebrar Texto Automaticamente** faz o texto descer em várias linhas dentro da própria célula, ajustando a altura da linha da planilha; a largura da coluna não muda.\n\nO ponto da quebra é decidido pelo Excel conforme a largura. Para escolher onde quebrar, usa-se Alt + Enter durante a digitação, o que insere uma quebra manual na célula.\n\nA banca pode confundir esse recurso com mesclar células ou dizer que ele aumenta a largura da coluna.",
