      "resumo": "**Delete** remove o **conteúdo** (dados e fórmulas) e **mantém** formatos e comentários. O botão **Limpar** (Página Inicial > Edição) oferece Limpar Tudo, Formatos, Conteúdo, Comentários e Hiperlinks. Fonte: Suporte Microsoft, \"Atalhos de teclado no Excel\" (consultado em 08/11/2026).",
