      "aprofundamento": "O **Delete** é uma limpeza parcial: tira o conteúdo, mas deixa a \"embalagem\" da célula, como cor de fundo, bordas, formato de número e comentários. Se depois se digitar um número numa célula que tinha formato de moeda, ele já aparece como moeda.\n\nPara escolher o que remover, existe o botão **Limpar**, na Página Inicial: limpar tudo, só formatos, só conteúdo, comentários ou hiperlinks. Excluir a célula, pelo botão direito, é outra coisa: remove a célula e desloca as vizinhas.\n\nA banca diz que o Delete apaga a formatação. Ele não apaga.",
