     "id": "INF-2.2.4-R1-02",
     "ponto": "DBA26-INF-2.2.4",
     "tema": "Colar Especial",
     "assertiva": "O Colar Especial (Ctrl + Alt + V) permite colar apenas os valores, apenas as fórmulas, apenas os formatos, transpor linhas e colunas ou operar o conteúdo copiado com o do destino.",
     "gabarito": "C",
     "comentario": {
      "resumo": "**Colar Especial**: **Valores** (o resultado, sem a fórmula), Fórmulas, Formatos, Comentários, **Transpor** (linhas ↔ colunas) e operações (somar, multiplicar...). Fonte: Suporte Microsoft, \"Atalhos de teclado no Excel\" (consultado em 08/11/2026).",
      "palavras_chave": [
       "Colar Especial",
       "Transpor"
      ],
      "aprofundamento": "O colar comum leva tudo: valor, fórmula, formato e comentário. O **Colar Especial** permite escolher a parte. Colar **Valores** é o uso mais comum: transforma o resultado de uma fórmula em número fixo, que não depende mais das células de origem.\n\n**Transpor** gira o bloco, transformando linhas em colunas e vice-versa. As operações combinam o copiado com o que já está no destino: por exemplo, copiar um valor e colar com multiplicar aplica o reajuste a uma coluna inteira.\n\nA banca pode trocar o atalho ou negar alguma das opções. A assertiva descreve corretamente o recurso.",
      "memorize": "Ctrl + Alt + V = Colar Especial: valores, fórmulas, formatos, transpor, operações."
     }
