      "aprofundamento": "A **alça de preenchimento** reconhece padrões. O Excel tem listas internas, como meses e dias da semana, por extenso ou abreviados; ao arrastar uma célula com um desses itens, ele continua a lista.\n\nCom números, precisa de pista: duas células com 1 e 2 indicam passo de um; com 2 e 4, passo de dois. Um número sozinho é apenas repetido, salvo se o usuário segurar Ctrl durante o arraste, que o faz incrementar. Datas, ao contrário, avançam dia a dia mesmo sozinhas.\n\nDepois do arraste, o botão Opções de Autopreenchimento permite trocar entre copiar células e preencher série.",
