      "aprofundamento": "A classificação aparece em dois lugares porque é muito usada. Na guia **Dados** ficam os botões de ordem crescente e decrescente e a caixa **Classificar**, mais completa. Na **Página Inicial**, o botão Classificar e Filtrar reúne as mesmas opções e o filtro.\n\nA caixa permite vários **níveis**: o primeiro critério manda e o segundo desempata dentro dele. Também é possível ordenar por cor da célula ou da fonte e por listas personalizadas.\n\nA banca pode dizer que só existe um nível ou que a classificação fica na guia Revisão.",
