      "aprofundamento": "Numa tabela, cada linha é um registro: nome, cargo e lotação de uma mesma pessoa. Ordenar só uma coluna separaria o nome do cargo, desalinhando tudo. Por isso o Excel detecta dados ao lado e exibe o aviso, sugerindo **expandir a seleção** para levar as colunas vizinhas junto.\n\nSe o usuário escolher continuar com a seleção atual, o Excel obedece e só aquela coluna é reordenada, com o risco de embaralhar os registros. Quando se clica numa única célula da tabela, o Excel já considera a região toda.\n\nA banca diz que o Excel reordena tudo \"sempre, sem consultar\". O aviso existe justamente para consultar.",
      "memorize": "Classificar uma coluna: Excel pergunta (expandir ou não). Não expandir desalinha."
