      "aprofundamento": "O gráfico não é uma imagem: é uma representação viva de um intervalo de células. Cada barra, ponto ou fatia está ligado a uma célula; mudou o valor, muda o desenho. É isso que permite usar o gráfico como painel de acompanhamento.\n\nO intervalo de origem pode ser alterado depois, pelo comando Selecionar Dados, para incluir novas linhas. Se os dados estiverem formatados como Tabela, linhas acrescentadas entram automaticamente.\n\nPara congelar o gráfico, desligando-o dos dados, é preciso copiá-lo e colá-lo como imagem. A assertiva está correta.",
