      "aprofundamento": "**Minigráficos** resumem uma linha de dados numa única célula, sem eixos nem legenda, apenas o desenho da tendência. São úteis em tabelas extensas, em que um gráfico completo para cada linha seria impraticável.\n\nHá três tipos: **Linha**, para tendência; **Coluna**, para comparar valores; e **Ganhos/Perdas**, que mostra só se cada valor é positivo ou negativo. Podem destacar o ponto mais alto, o mais baixo e os negativos.\n\nA banca pode confundi-los com gráficos comuns ou dizer que ocupam folha própria. Eles vivem dentro da célula.",
