      "aprofundamento": "A diferença é de alcance. A **transição** acontece entre um slide e outro: é o modo como o slide seguinte entra na tela, como esmaecer ou empurrar. Por isso tem guia própria, Transições, e é aplicada ao slide inteiro.\n\nA **animação** acontece dentro do slide: faz um título, imagem ou item de lista entrar, destacar-se, sair ou percorrer uma trajetória. Fica na guia Animações e é aplicada a cada objeto.\n\nA banca inverte os conceitos. Pense na palavra: transição é passagem, mudança de um lugar para outro.",
