      "aprofundamento": "**Formatar Plano de Fundo** abre um painel com as opções de preenchimento: cor sólida, gradiente (transição entre cores), imagem ou textura e padrão. Também é possível ocultar os gráficos de fundo do tema, como faixas e logotipos.\n\nPor padrão, a mudança vale só para o slide selecionado. O botão **Aplicar a Todos** estende a mudança à apresentação inteira; outra via é alterar o fundo no slide mestre.\n\nA banca pode situar o comando em outra guia ou dizer que ele só aceita cores. A assertiva está correta.",
