      "aprofundamento": "**Criar Folhetos** leva a apresentação para o Word, onde é mais fácil montar material impresso ou editar textos de apoio. O PowerPoint oferece layouts: anotações ao lado ou abaixo dos slides, linhas em branco para o público escrever, ou só a estrutura de tópicos.\n\nEscolhendo **colar vínculo**, os slides no Word acompanham mudanças na apresentação; escolhendo colar, ficam como cópia fixa.\n\nA banca pode situar o comando em outra guia ou dizer que ele só exporta para PDF. A assertiva aponta o caminho correto, em Arquivo > Exportar.",
