      "aprofundamento": "Por padrão, colar células do Excel no PowerPoint gera uma **tabela** nativa do PowerPoint, que se edita no próprio slide e ganha as guias contextuais de tabela. Ela não tem fórmulas: os valores chegam como texto fixo.\n\nAs **Opções de Colagem**, que aparecem logo após colar, oferecem alternativas: manter a formatação de origem, usar o estilo do destino, incorporar como objeto do Excel, colar como imagem ou manter só o texto. Para acompanhar a planilha, usa-se Colar vínculo.\n\nA banca pode dizer que a colagem padrão sempre cria vínculo. A assertiva descreve corretamente o padrão.",
