      "resumo": "O **Edge** atual é baseado no **Chromium** (projeto aberto que também está por trás do Chrome) desde 2020; o **Firefox** usa o motor próprio **Gecko**, da Mozilla.",
      "pegadinha": "Trocar Chromium por Gecko.",
