     "assertiva": "A invasão de dispositivo informático alheio para obter dados sem autorização é crime previsto no Código Penal, ainda que organizada ou praticada por meio da dark web.",
     "gabarito": "C",
     "comentario": {
      "resumo": "O meio não afasta o crime: a **invasão de dispositivo informático** está no **art. 154-A** do CP (Lei 12.737/2012, com penas da Lei 14.155/2021), e a anonimização só dificulta a investigação.",
      "lei": [
       {
        "lei": "CP",
        "art": "154-A",
        "par": "",
        "inc": "",
        "rotulo": "CP, art. 154-A, caput",
        "texto": "Invadir dispositivo informático de uso alheio, conectado ou não à rede de computadores, com o fim de obter, adulterar ou destruir dados ou informações sem autorização expressa ou tácita do usuário do dispositivo"
       }
      ],
      "palavras_chave": [
       "invasão de dispositivo informático",
       "art. 154-A"
      ],
      "aprofundamento": "O tipo penal descreve a conduta, não o meio técnico de anonimato. Quem **invade dispositivo informático alheio** para obter, adulterar ou destruir dados sem autorização pratica o crime do art. 154-A do CP, esteja ele usando conexão comum, VPN ou Tor. O tipo protege a intimidade e a segurança dos dados e alcança o dispositivo conectado ou não à rede.\n\nA dark web interessa à investigação, não à tipicidade: ela dificulta a identificação do autor, exige técnicas de rastreamento e cooperação, mas não cria espaço livre de lei.\n\nRepare nos elementos do caput citado: dispositivo **de uso alheio**, finalidade de obter, adulterar ou destruir dados, e ausência de autorização expressa ou tácita. A banca costuma retirar a finalidade ou a falta de autorização para ver se o aluno percebe.",
      "exemplo": "Marcos usa o Tor para invadir o notebook de um colega e copiar fotos dele; responde pela invasão de dispositivo, e o anonimato só torna mais trabalhosa a identificação.",
      "memorize": "O meio (dark web, VPN) não afasta o art. 154-A; só dificulta achar o autor."
     }
