      "aprofundamento": "O endereço de e-mail funciona como endereço postal em duas partes. À direita da arroba fica o **domínio**: é por ele que o servidor remetente consulta o DNS e descobre qual servidor de correio recebe mensagens para aquele endereço. À esquerda fica a **caixa postal**, que só o servidor de destino precisa interpretar.\n\nNo exemplo, a mensagem segue primeiro para o servidor responsável por pc.ba.gov.br, que então a entrega à caixa 'delegado'. O domínio, por sua vez, se lê da direita para a esquerda: br, gov, ba, pc, do mais geral ao mais específico.\n\nA banca inverte as partes ou diz que o endereço admite espaços. Não admite; e a arroba é obrigatória e única.",
