      "aprofundamento": "Os três campos de destinatário diferem só na **visibilidade**. Quem está em Para e em Cc aparece no cabeçalho que todos recebem; o Cc é cópia de cortesia, para quem precisa saber mas não é o destinatário principal. O **Cco**, cópia carbono oculta, retira o endereço do cabeçalho entregue aos demais: cada destinatário oculto recebe a mensagem, mas ninguém sabe que ele está ali.\n\nO uso típico é o envio em massa, que protege a privacidade dos endereços e dificulta a coleta por spammers. Uma consequência que a banca adora: o 'Responder a todos' de quem estava em Para ou Cc não alcança o destinatário oculto, porque ele não consta do cabeçalho.\n\nA troca clássica é inverter Cc e Cco. Oculta é oculta: ninguém vê.",
