      "resumo": "**Alt + Enter** mostra as **propriedades** do item (tamanho, local, datas, atributos). Excluir é Delete (para a Lixeira) ou Shift + Delete (definitivo). Fonte: Suporte Microsoft, \"Atalhos de teclado no Windows\" (consultado em 08/11/2026).",
