      "aprofundamento": "Os **modos de exibição** existem porque cada tarefa pede uma visão. Ícones grandes servem para fotos; Lista cabe muitos itens na tela; **Detalhes** mostra colunas com nome, data de modificação, tipo e tamanho; Blocos e Conteúdo ficam no meio-termo, com miniatura e algumas informações.\n\nNo modo Detalhes, o cabeçalho da coluna é clicável: um clique ordena por aquele critério, o segundo inverte a ordem. Com o botão direito no cabeçalho, escolhem-se outras colunas, como autor ou dimensões.\n\nA banca costuma negar a ordenação pelo cabeçalho ou inventar modos inexistentes. O ponto mais cobrado é a ordenação no modo Detalhes.",
