      "aprofundamento": "O **Limpar Toda a Formatação** (botão com A e borracha, no grupo Fonte) devolve o trecho ao padrão: remove negrito, cor, tamanho e fonte aplicados e volta ao estilo **Normal**. O texto continua lá, apenas sem o 'vestido'.\n\nÉ útil quando se cola conteúdo de outra fonte, como site ou e-mail, e ele chega com formatos estranhos. Para o mesmo fim, há também o Colar Especial, mantendo só o texto.\n\nA pegadinha confunde limpar formatação com apagar. Para apagar texto, usam-se Delete ou Backspace; o comando de limpar só mexe na aparência.",
      "memorize": "Limpar formatação tira a aparência, não o texto."
