     "assertiva": "Na caixa Mais Colunas, é possível exigir colunas de mesma largura e inserir uma linha vertical entre elas.",
     "gabarito": "C",
     "comentario": {
      "resumo": "Em **Mais Colunas** marcam-se **Colunas de mesma largura** e **Linha entre colunas**, e se escolhe a partir de onde aplicar (documento inteiro ou deste ponto em diante).",
      "palavras_chave": [
       "Linha entre colunas",
       "Mais Colunas"
      ],
      "aprofundamento": "Os botões rápidos de Colunas, na guia Layout, aplicam modelos prontos. A caixa **Mais Colunas** dá o controle fino: quantidade, largura e espaçamento de cada coluna, a opção **Colunas de mesma largura** e a **Linha entre colunas**, que desenha uma linha vertical separando-as, como em jornal.\n\nO campo 'Aplicar a' decide o alcance: documento inteiro ou **deste ponto em diante**. Nessa segunda opção, o Word insere quebra de seção, porque o número de colunas é configuração de seção.\n\nA banca costuma dizer que a linha entre colunas exige desenhar uma forma, ou que colunas valem sempre para o documento inteiro.",
      "memorize": "Mais Colunas: mesma largura, linha entre colunas e 'deste ponto em diante' (nova seção)."
     }
