      "aprofundamento": "No modo Layout de Impressão, o Word separa a área do corpo da área de cabeçalho e rodapé. Quando se edita uma, a outra fica **esmaecida**, para mostrar que não está ativa. Entra-se no cabeçalho com duplo clique sobre ele e sai-se com duplo clique no corpo do documento.\n\nA saída também pode ser pelo botão **Fechar Cabeçalho e Rodapé**, na guia contextual que aparece durante a edição, ou pela tecla Esc. Essa guia só existe enquanto o cabeçalho está ativo, como as demais guias contextuais do Office.\n\nA banca costuma dizer que só o botão fecha a edição. O duplo clique funciona nos dois sentidos.",
