      "aprofundamento": "Por padrão, o Excel ordena **linhas**: cada linha é um registro, e a ordem muda de cima para baixo conforme os valores de uma coluna. Em algumas tabelas, a estrutura é a inversa, com os registros em colunas, como meses lado a lado.\n\nPara elas, o botão **Opções** da caixa Classificar permite mudar a orientação para **da esquerda para a direita**: o critério passa a ser uma linha, e são as colunas que mudam de posição. Na mesma tela há a opção de diferenciar maiúsculas e minúsculas, desligada por padrão.\n\nA banca costuma negar essa possibilidade ou dizer que só a transposição resolveria. Não é preciso transpor.",
