      "aprofundamento": "Escolher o gráfico errado distorce a leitura: série no tempo pede linha; comparação entre categorias, colunas ou barras; partes de um todo, pizza. O **Gráficos Recomendados** analisa a seleção, olhando quantas séries há, se há datas e categorias, e sugere tipos adequados, com prévia.\n\nDepois de inserido, o gráfico passa a ter guias **contextuais**, que só aparecem quando ele está selecionado: Design do Gráfico, para tipo, layout, estilos e dados, e Formatar, para cores, contornos e efeitos dos elementos.\n\nA banca costuma situar o comando na guia Dados ou dizer que as guias de gráfico ficam sempre visíveis.",
