      "aprofundamento": "Apresentações longas ficam difíceis de navegar como fila única de miniaturas. As **seções** agrupam slides em blocos nomeados, como 'Introdução', 'Casos' e 'Conclusão', que aparecem no painel e no Classificador de Slides.\n\nCom elas, é possível recolher e expandir blocos, mover uma seção inteira de lugar arrastando o nome, e dividir o trabalho entre autores. A criação fica em Página Inicial > Seção > Adicionar Seção, ou com o botão direito entre duas miniaturas.\n\nA assertiva nega um recurso que existe. Seções organizam; não aparecem para o público durante a apresentação.",
