      "aprofundamento": "Toda forma do PowerPoint é um contorno definido por pontos e curvas. Em **Editar Forma > Editar Pontos**, esses pontos aparecem e podem ser arrastados, acrescentados ou removidos, e as curvas, ajustadas pelas alças. Assim um retângulo vira mapa simplificado, ou uma seta ganha curvatura própria.\n\nSe a necessidade é só trocar o tipo, **Alterar Forma** substitui a forma por outra da galeria, mantendo texto, cor e tamanho.\n\nA assertiva diz que o contorno é imutável depois de desenhado. As duas opções ficam no mesmo botão, Editar Forma, na guia Formato da Forma.",
