      "aprofundamento": "A **numeração** das listas do PowerPoint, na Página Inicial, grupo Parágrafo, oferece formatos variados: algarismos arábicos, **romanos** em maiúsculas ou minúsculas, letras com ponto ou parêntese. Em Marcadores e Numeração, define-se também tamanho e cor do número.\n\nO campo **Iniciar em** permite começar em outro valor, útil quando uma lista continua em outro slide: o segundo slide pode começar no item seguinte ao último do anterior.\n\nA banca costuma dizer que o PowerPoint só numera com arábicos, ou que toda lista começa obrigatoriamente em 1.",
