     "gabarito": "E",
     "comentario": {
      "resumo": "A **engenharia social** explora a **confiança e o descuido das pessoas** (falso suporte técnico, falso parente pedindo PIX); antivírus não resolve — a defesa é **desconfiar e confirmar por outro canal**. Fonte: Cartilha de Segurança para Internet, CERT.br (cartilha.cert.br, consultada em 08/11/2026).",
      "pegadinha": "Reduzir a engenharia social a falha técnica.",
      "palavras_chave": [
       "engenharia social",
       "confirmar por outro canal"
      ],
      "correcao": {
       "erro": "Afirma que a engenharia social explora falhas técnicas do sistema e é integralmente evitada por antivírus atualizado.",
       "certo": "A engenharia social explora a confiança e o descuido das pessoas; antivírus não resolve, e a defesa é desconfiar e confirmar por outro canal."
      },
      "aprofundamento": "A **engenharia social** ataca o elo humano: em vez de quebrar a técnica, convence a pessoa a abrir a porta. O golpista se passa por suporte técnico, gerente do banco ou parente em apuros, cria urgência e pede senha, código ou transferência. O sistema funciona perfeitamente; quem age é a vítima.\n\nPor isso o antivírus não resolve: não há programa malicioso para detectar quando a própria pessoa digita a senha ou faz o PIX. A defesa é comportamental: desconfiar de pedidos urgentes, não fornecer códigos e confirmar a história por **outro canal**, ligando para o número conhecido.\n\nA assertiva reduz o ataque a falha técnica e promete solução integral por software. As duas ideias estão erradas.",
      "memorize": "Engenharia social ataca a pessoa, não o sistema. Defesa: desconfiar e confirmar por outro canal."
     }
