      "aprofundamento": "O § 2º-B do art. 171 é **causa de aumento** que incide sobre a pena da fraude eletrônica do § 2º-A: de 1/3 a 2/3, se o crime é praticado mediante servidor mantido fora do território nacional. A razão é a maior dificuldade de investigação: dados no exterior exigem cooperação internacional, mais lenta, e facilitam a impunidade.\n\nO texto exige que se considere a **relevância do resultado gravoso** ao fixar a fração, de modo que o aumento acompanhe a gravidade do dano causado.\n\nA banca troca a fração, aplica o aumento ao estelionato simples ou o condiciona a o autor estar no exterior. O que importa é o **servidor** fora do país.",
