      "aprofundamento": "O **Arquivos Sob Demanda** resolve o conflito entre ter tudo à mão e ter pouco espaço no disco. O Explorador mostra todos os arquivos do OneDrive, mas o conteúdo só é baixado quando necessário. Os ícones indicam o estado: **nuvem**, só online; marca de verificação, baixado; círculo verde preenchido, **sempre mantido** no dispositivo.\n\nAbrir um arquivo só online exige conexão. O arquivo marcado como 'Sempre manter neste dispositivo' fica disponível offline; o comando 'Liberar espaço' devolve o arquivo ao estado só online.\n\nA banca costuma dizer que o recurso baixa tudo automaticamente, ou que o arquivo só online não aparece no Explorador. Ele aparece, só não ocupa espaço.",
