      "aprofundamento": "O backup existe para sobreviver ao que destrói o original. Se a cópia fica no **mesmo disco**, o defeito físico, o furto do computador ou um ransomware que cifra tudo o que encontra levam original e cópia ao mesmo tempo. A segunda cópia vira ilusão de proteção.\n\nPor isso as boas práticas pedem **outra mídia**, como disco externo, servidor ou nuvem, e, para os desastres maiores, **outro local**, o que a regra 3-2-1 resume. Uma pasta de cópia no mesmo disco ajuda apenas contra exclusão acidental.\n\nA assertiva atribui ao backup no mesmo disco proteção justamente contra a falha física desse disco, que é a ameaça que ele não cobre.",
